// The webhook puts the POSTed JSON under `body`.
const clip = $json.body || $json;
const safe = s => String(s || '').replace(/[^A-Za-z0-9_\-]/g, '');
const start = Number(clip.start_time), end = Number(clip.end_time);
return {
  vod_id: clip.vod_id, vod_url: clip.vod_url || `https://www.twitch.tv/videos/${clip.vod_id}`,
  start_time: start, end_time: end, duration: end - start,
  streamer: clip.streamer || '', game: clip.game || '', title: clip.title || '', reason: clip.reason || '',
  score: clip.score || '', clip_id: safe(clip.clip_id || `clip_${clip.vod_id}_${start}`),
};

// Fetch just the HLS segments covering the clip (scripts/twitch_section.py: ffmpeg stalls on
// Twitch's fMP4 playlists). Prints JSON with the offset of start_time inside the file.
const { vod_url, start_time, end_time, clip_id } = $json;
const rawPath = `/temp/${clip_id}_raw.mp4`;
const cmd = `python3 /scripts/twitch_section.py "${vod_url}" ${start_time} ${end_time} "${rawPath}" 1080`;
return { ...$json, cmd, rawPath, wavPath: `/temp/${clip_id}.wav`,
         captionPath: `/temp/${clip_id}_captions.srt`, outputPath: `/output/${clip_id}.mp4` };

// Exact clip audio (16 kHz mono) -> whisper.cpp subtitles.
const clip = $('Generate Extract Command').item.json;
let dl;
try { dl = JSON.parse($json.stdout); } catch (e) { throw new Error('Download failed: ' + ($json.stdout || $json.stderr)); }
if (dl.error) throw new Error('Download failed: ' + dl.error);
const trim = `-ss ${dl.offset} -t ${dl.duration}`;
const captionCmd = `ffmpeg -nostdin -v error -y ${trim} -i "${clip.rawPath}" -vn -ar 16000 -ac 1 "${clip.wavPath}" && ` +
  `whisper-cli -np -t $(nproc) -m /models/ggml-base.en.bin -f "${clip.wavPath}" -osrt -of "${clip.captionPath.replace(/\.srt$/, '')}"`;
return { ...clip, trim, captionCmd };

// ONE encode: 9:16 crop -> 1080x1920 @30fps, burned captions, streamer tag, title, watermark,
// loudness normalisation. x264 veryfast keeps a 30 s clip to a few minutes on 1 vCPU.
const clip = $('Generate Caption Command').item.json;
const esc = s => String(s || '').replace(/['":\\%,;\[\]]/g, '').substring(0, 50);
const style = 'Fontname=DejaVu Sans,Fontsize=12,PrimaryColour=&HFFFFFF&,Outline=2,OutlineColour=&H000000&,Alignment=2,MarginV=60';
const vf = `[0:v]crop=ih*9/16:ih:(iw-ow)/2:0,scale=1080:1920,fps=30,` +
  `subtitles='${clip.captionPath}':force_style='${style}',` +
  `drawtext=text='@${esc(clip.streamer)}':fontsize=44:fontcolor=white:x=w-tw-30:y=60:box=1:boxcolor=black@0.5:boxborderw=10,` +
  `drawtext=text='${esc(clip.title)}':fontsize=40:fontcolor=white:x=(w-tw)/2:y=h-260:box=1:boxcolor=black@0.5:boxborderw=10[base];` +
  `[1:v]scale=200:-1[wm];[base][wm]overlay=W-w-30:H-h-120[v]`;
const finalCmd = `ffmpeg -nostdin -v error -y ${clip.trim} -i "${clip.rawPath}" -i /scripts/assets/watermark.png -filter_complex "${vf}" ` +
  `-map "[v]" -map 0:a? -af "loudnorm=I=-16:TP=-1.5:LRA=11" -c:v libx264 -preset veryfast -crf 23 ` +
  `-c:a aac -b:a 128k -movflags +faststart "${clip.outputPath}" && rm -f "${clip.rawPath}" "${clip.wavPath}" "${clip.captionPath}"`;
return { ...clip, finalCmd };

// Check the render exists; upload to Cloudflare R2 when R2 keys and the aws CLI are available.
const fs = require('fs');
const { execSync } = require('child_process');
const clip = $('Generate Final Render Command').item.json;
if (!fs.existsSync(clip.outputPath)) throw new Error('Output file not found: ' + clip.outputPath);
const file_size_mb = (fs.statSync(clip.outputPath).size / 1024 / 1024).toFixed(2);

let video_url = clip.outputPath;
if ($env.R2_ACCOUNT_ID && $env.R2_ACCESS_KEY_ID && $env.R2_SECRET_ACCESS_KEY) {
  const bucket = $env.R2_BUCKET_NAME || 'tiktok-clips';
  const key = `clips/${clip.clip_id}.mp4`;
  try {
    execSync(`aws s3 cp "${clip.outputPath}" "s3://${bucket}/${key}" --endpoint-url https://${$env.R2_ACCOUNT_ID}.r2.cloudflarestorage.com`, {
      stdio: 'pipe', timeout: 300000,
      env: { ...process.env, AWS_ACCESS_KEY_ID: $env.R2_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY: $env.R2_SECRET_ACCESS_KEY, AWS_DEFAULT_REGION: 'auto' },
    });
    video_url = $env.R2_PUBLIC_URL ? `${$env.R2_PUBLIC_URL.replace(/\/$/, '')}/${key}` : video_url;
  } catch (err) {
    console.log('R2 upload failed, keeping local path:', err.message);
  }
}
return {
  clip_id: clip.clip_id, vod_id: clip.vod_id, streamer: clip.streamer, game: clip.game,
  start_time: clip.start_time, end_time: clip.end_time, title: clip.title, reason: clip.reason,
  score: clip.score, video_path: clip.outputPath, video_url, file_size_mb, status: 'ready_to_post', posted_at: '',
};
